^darkgray;최대 에너지: -^reset;
^darkgray;에너지 재생: -^reset;
^white;공격 배율^reset;: ^green;+5%^reset;
^darkgray;방어력: -^reset;
    ^#00A9FF;저항^reset;
^darkgray;화염 저항: -^reset;
^darkgray;전기 저항: -^reset;
^white;독 저항^reset;: ^green;+10%^reset;
^white;냉기 저항^reset;: ^green;+10%^reset;
^darkgray;물리 저항: -^reset;
    ^#00A9FF;면역^reset;: ^green;식중독
    ^#00A9FF;종족 특성^reset;: -
^white;낙하 피해^reset;: ^green;-75%^reset;, ^white;넉백 저항^reset;: ^green;+4%^reset;, ^white;점프 높이^reset;: ^green;+10%^reset;, ^white;이동 속도^reset;: ^green;+5%^reset;, ^white;최대 호흡^reset;: ^green;+25.0^reset;, ^white;배고픔 속도^reset;: ^red;+5%^reset;
